/// Returns the index of the first minimum element in a non‐empty vector.
///
/// Specification:
///   - Precondition: `a.len() > 0`
///   - Postcondition: `result < a.len()`
///   - Postcondition: For every `i` in `0..a.len()`, `a[result] <= a[i]`
///   - Postcondition: For every `j < result`, `a[j] > a[result]` (so we pick the *first* minimum).
#[requires(a.len() > 0)]
#[ensures(result < a.len())]
#[ensures(forall(|i: usize| i < a.len() ==> a[result] <= a[i]))]
#[ensures(forall(|j: usize| j < result ==> a[j] > a[result]))]
fn getmini(a: &Vec<i32>) -> usize {
    // We re‐check the precondition at run‐time for safety
    assert!(a.len() > 0, "Input vector must be non-empty");

    let mut min_index = 0;
    let mut min_value = a[0];

    // Loop over the rest of the elements, maintaining that:
    //   1) 1 ≤ i ≤ a.len()
    //   2) min_index < i
    //   3) For all k < i, a[min_index] ≤ a[k]
    // and we decrease a.len() - i each iteration.
    #[invariant(i <= a.len())]
    #[invariant(min_index < i)]
    #[invariant(forall(|k: usize| k < i ==> a[min_index] <= a[k]))]
    #[decreases(a.len() - i)]
    for (i, &val) in a.iter().enumerate().skip(1) {
        if val < min_value {
            min_value = val;
            min_index = i;
        }
    }

    min_index
}

